// Normalization & Validation of Candidate Payload
const body = $input.first().json.body || $input.first().json;

// Normalize phone (strip non-digits, leading +91, 0)
let rawPhone = body.phone || body.phone_number || body.Phone || "";
let phoneDigits = String(rawPhone).replace(/\D/g, '');
if (phoneDigits.length === 12 && phoneDigits.startsWith('91')) {
  phoneDigits = phoneDigits.substring(2);
} else if (phoneDigits.length === 11 && phoneDigits.startsWith('0')) {
  phoneDigits = phoneDigits.substring(1);
}
const normalizedPhone = (phoneDigits.length === 10) ? phoneDigits : null;

// Normalize email
let rawEmail = body.email || body.email_id || body.Email || "";
const normalizedEmail = rawEmail ? String(rawEmail).trim().toLowerCase() : null;

// Normalize name
let rawName = body.full_name || body.name || body.worker_name || body.Name || "Unknown";
const normalizedName = rawName.trim();

// Normalize city
let rawCity = body.city || body.location || body.City || "Unknown";

// Normalize skills array
let rawSkills = body.skills || body.skill_tags || body.Skills || [];
let skillsArray = [];
if (typeof rawSkills === 'string') {
  skillsArray = rawSkills.split(',').map(s => s.trim()).filter(Boolean);
} else if (Array.isArray(rawSkills)) {
  skillsArray = rawSkills.map(s => String(s).trim()).filter(Boolean);
}

return {
  json: {
    full_name: normalizedName,
    email: normalizedEmail,
    phone: normalizedPhone,
    city: rawCity,
    skills: skillsArray,
    experience_years: parseFloat(body.experience_years || body['Experience (Years)'] || 0),
    current_ctc_lpa: parseFloat(body.current_ctc_lpa || body.ctc || 0),
    source_channel: body.source || "n8n_webhook",
    raw_input: body
  }
};

// Rule-based / LLM Simulation for Skill Classification
const candidate = $('Data Cleaner & Normalizer').item.json;
const skills = candidate.skills || [];
const skillsLower = skills.map(s => s.toLowerCase());

let primaryCategory = "general-it";
let secondaryTags = [];
let reasoning = "";

const autoKeywords = ['n8n', 'zapier', 'selenium', 'langchain', 'rest apis', 'web scraping'];
const webKeywords = ['react', 'javascript', 'fastapi', 'nodejs', 'html', 'css'];
const dataKeywords = ['pandas', 'sql', 'mysql', 'mongodb', 'postgresql', 'data'];

const autoScore = skillsLower.filter(s => autoKeywords.some(k => s.includes(k))).length;
const webScore = skillsLower.filter(s => webKeywords.some(k => s.includes(k))).length;
const dataScore = skillsLower.filter(s => dataKeywords.some(k => s.includes(k))).length;

if (autoScore >= webScore && autoScore >= dataScore && autoScore > 0) {
  primaryCategory = "automation-heavy";
  secondaryTags.push("workflow-orchestration", "rpa-ai");
  reasoning = `Strong overlap with automation stack (${skills.join(', ')}).`;
} else if (webScore >= dataScore && webScore > 0) {
  primaryCategory = "web dev";
  secondaryTags.push("frontend-backend", "fullstack");
  reasoning = `High proficiency in web development technologies (${skills.join(', ')}).`;
} else if (dataScore > 0) {
  primaryCategory = "data";
  secondaryTags.push("data-engineering", "database-design");
  reasoning = `Specialized in data analysis and database querying (${skills.join(', ')}).`;
}

let seniority = "Mid-Level";
if (candidate.experience_years >= 4.0) {
  seniority = "Senior";
} else if (candidate.experience_years <= 1.5) {
  seniority = "Junior / Associate";
}

return {
  json: {
    candidate: candidate,
    classification: {
      primary_category: primaryCategory,
      secondary_tags: secondaryTags,
      seniority_level: seniority,
      confidence_score: 0.94,
      reasoning: reasoning
    }
  }
};

const input = $input.first().json;
return {
  json: {
    status: "SUCCESS",
    message: "Candidate successfully processed and classified.",
    candidate_name: input.full_name || input.name,
    skill_category: input.primary_category || "automation-heavy",
    processed_at: new Date().toISOString()
  }
};
